if (window.innerWidth >= 993) {
    const wrap = document.querySelector('.stages__wrap');
    const shine = document.querySelector('.global-shine');

    const groups = document.querySelectorAll('.stages__group');

    const group1 = groups[0];
    const group2 = groups[1];
    const group3 = groups[2];

    const line1 = group1.querySelector('.line-main');
    const vertical1 = group1.querySelector('.line-glow-vertical');

    const line2 = group2.querySelector('.line-main');
    const vertical2 = group2.querySelector('.line-glow-vertical');

    const line3 = group3.querySelector('.line-main');

    const icons1 = group1.querySelectorAll('.stages__item-icon');
    const icons2 = group2.querySelectorAll('.stages__item-icon');
    const icons3 = group3.querySelectorAll('.stages__item-icon');

    const allIcons = document.querySelectorAll('.stages__item-icon');

    gsap.set(allIcons, {
        opacity: 0,
        scale: 0.75,
        rotate: -10
    });

    gsap.set(shine, {
        opacity: 1,
        x: -120,
        y: 0
    });

    function getCoords(el) {
        const wrapRect = wrap.getBoundingClientRect();
        const rect = el.getBoundingClientRect();

        return {
            x: rect.left - wrapRect.left,
            y: rect.top - wrapRect.top
        };
    }

    function updatePositions() {
        return {
            line1: getCoords(line1),
            vertical1: getCoords(vertical1),
            line2: getCoords(line2),
            vertical2: getCoords(vertical2),
            line3: getCoords(line3)
        };
    }

    let pos = updatePositions();

    window.addEventListener('resize', () => {
        pos = updatePositions();
        ScrollTrigger.refresh();
    });

    const tl = gsap.timeline({
        scrollTrigger: {
            trigger: '.stages__wrap',
            start: 'top 60%',
            end: 'bottom bottom',
            scrub: 3
        }
    });

    tl.to(shine, {
        x: pos.line1.x + line1.offsetWidth - 120,
        duration: 4,
        ease: 'none'
    });

    tl.to(icons1[0], {
        opacity: 1,
        scale: 1,
        rotate: 0,
        duration: 1,
        ease: 'power3.out'
    }, '-=3.2');

    tl.to(icons1[1], {
        opacity: 1,
        scale: 1,
        rotate: 0,
        duration: 1,
        ease: 'power3.out'
    }, '-=2');

    tl.to(shine, {
        x: pos.vertical1.x,
        y: pos.vertical1.y + vertical1.offsetHeight - 120,
        duration: 2,
        ease: 'none'
    });

    tl.to(shine, {
        x: pos.line2.x + line2.offsetWidth - 120,
        y: pos.line2.y,
        duration: 0.6,
        ease: 'none'
    });

    tl.to(shine, {
        x: pos.line2.x,
        duration: 4,
        ease: 'none'
    });

    tl.to(icons2[1], {
        opacity: 1,
        scale: 1,
        rotate: 0,
        duration: 1,
        ease: 'power3.out'
    }, '-=3.2');

    tl.to(icons2[0], {
        opacity: 1,
        scale: 1,
        rotate: 0,
        duration: 1,
        ease: 'power3.out'
    }, '-=2');

    tl.to(shine, {
        x: pos.vertical2.x,
        y: pos.vertical2.y + vertical2.offsetHeight - 120,
        duration: 2,
        ease: 'none'
    });

    tl.to(shine, {
        x: pos.line3.x,
        y: pos.line3.y,
        duration: 0.6,
        ease: 'none'
    });

    tl.to(shine, {
        x: pos.line3.x + line3.offsetWidth - 0,
        duration: 4,
        ease: 'none'
    });

    tl.to(icons3[0], {
        opacity: 1,
        scale: 1,
        rotate: 0,
        duration: 1,
        ease: 'power3.out'
    }, '-=3.2');

    tl.to(icons3[1], {
        opacity: 1,
        scale: 1,
        rotate: 0,
        duration: 1,
        ease: 'power3.out'
    }, '-=2');
}

// bout-advantage
if (window.innerWidth >= 993) {
    const cards = gsap.utils.toArray('.about-advantage__card');

    const orderedCards = [
        cards[0],
        cards[1],
        cards[3],
        cards[2],
    ].filter(Boolean);

    const tl = gsap.timeline({
        scrollTrigger: {
            trigger: '.about-advantages__cards',
            start: 'top 50%',
            once: true,
        }
    });

    orderedCards.forEach((card, index) => {
        const arrow = card.querySelector('.arrow');

        gsap.set(card, {
            opacity: 0,
            y: 80
        });

        let arrowAnimation = {
            opacity: 0,
            x: 0,
            y: 0
        };

        switch (index) {
            case 0: 
                arrowAnimation.x = -60;
                break;

            case 1: 
                arrowAnimation.y = -60;
                break;

            case 2: 
                arrowAnimation.x = 60;
                break;

            case 3: 
                arrowAnimation.y = 60;
                break;
        }

        if (arrow) {
            gsap.set(arrow, arrowAnimation);
        }

        tl.to(card, {
            opacity: 1,
            y: 0,
            duration: 0.8,
            ease: 'power3.out'
        });

        if (arrow) {
            tl.to(arrow, {
                opacity: 1,
                x: 0,
                y: 0,
                duration: 0.45,
                ease: 'power3.out'
            }, '-=0.15');
        }
    });
}

if (window.innerWidth <= 992) {
    document.addEventListener("DOMContentLoaded", () => {

        const cards = document.querySelectorAll(".about-advantage__card");

        cards.forEach((card) => {
            gsap.set(card, {
                opacity: 0,
                y: 80
            });

            gsap.to(card, {
                opacity: 1,
                y: 0,
                duration: 1,
                ease: "power3.out",
                scrollTrigger: {
                    trigger: card,
                    start: "top 85%",
                    toggleActions: "play none none reverse"
                }
            });
        });
    });
}

